{"file_path":"/tmp/claude-0/-home-user-deepseek-harness/f53f80cc-1f77-5d02-a862-99d59ffabdce/scratchpad/bench/runs/e1-haiku-vs-sonnet-t3/cell-zTK5F2/src/dsu.js","old_string":"  /**
   * Joins two sets, attaching the smaller under the larger and, on a tie, the
   * larger root index under the smaller.
   * @param {number} a First element.
   * @param {number} b Second element.
   * @returns {boolean} False when both elements already shared a set.
   */
  union(a, b) {
    const rootA = this.find(a);
    const rootB = this.find(b);
    if (rootA === rootB) return false;
    const root = this.#size[rootB] > this.#size[rootA] ? rootB : rootA;
    const attached = root === rootA ? rootB : rootA;
    this.#parent[attached] = root;
    this.#size[root] += this.#size[attached];
    this.#components -= 1;
    return true;
  }","new_string":"  /**
   * Joins two sets, attaching the smaller under the larger and, on a tie, the
   * larger root index under the smaller.
   * @param {number} a First element.
   * @param {number} b Second element.
   * @returns {boolean} False when both elements already shared a set.
   */
  union(a, b) {
    this.#validateElement(a);
    this.#validateElement(b);
    const rootA = this.find(a);
    const rootB = this.find(b);
    if (rootA === rootB) return false;
    const root = this.#size[rootB] > this.#size[rootA] ? rootB : rootA;
    const attached = root === rootA ? rootB : rootA;
    // Record the union in history before making the change
    this.#history.push({ root, attached, rootASize: this.#size[rootA], rootBSize: this.#size[rootB] });
    this.#parent[attached] = root;
    this.#size[root] += this.#size[attached];
    this.#components -= 1;
    this.#unions += 1;
    return true;
  }"}

